import{_ as t,o as r,c as a,ag as u}from"./chunks/framework.CukOUUOK.js";const h=JSON.parse('{"title":"从沸腾到冰封：中国政治热情的四十年退潮史","description":"引子：一张被遗忘的快照 1978年冬，北京西单路口。 一面砖墙上贴满了大字报，围观的人从清晨站到深夜。有人踮脚抄录，有人低声争论，有人从外地坐火车专程赶来看。魏京生的《第五个现代化》贴在墙上最显眼的位…","frontmatter":{"title":"从沸腾到冰封：中国政治热情的四十年退潮史","categories":"权力与制度","tags":["历史","社会心理","权力"],"description":"引子：一张被遗忘的快照 1978年冬，北京西单路口。 一面砖墙上贴满了大字报，围观的人从清晨站到深夜。有人踮脚抄录，有人低声争论，有人从外地坐火车专程赶来看。魏京生的《第五个现代化》贴在墙上最显眼的位…","date":"2026-08-28T12:00:00.000Z","series":"莫谈国事","seriesOrder":3},"headers":[],"relativePath":"posts/2026-08-28-from-boiling-to-frozen.md","filePath":"posts/2026-08-28-from-boiling-to-frozen.md","lastUpdated":1789992750000}'),n={name:"posts/2026-08-28-from-boiling-to-frozen.md"};function q(s,o,e,l,p,i){return r(),a("div",null,[...o[0]||(o[0]=[u('<h1 id="从沸腾到冰封-中国政治热情的四十年退潮史" tabindex="-1">从沸腾到冰封：中国政治热情的四十年退潮史 <a class="header-anchor" href="#从沸腾到冰封-中国政治热情的四十年退潮史" aria-label="Permalink to &quot;从沸腾到冰封：中国政治热情的四十年退潮史&quot;">​</a></h1><h2 id="引子-一张被遗忘的快照" tabindex="-1">引子：一张被遗忘的快照 <a class="header-anchor" href="#引子-一张被遗忘的快照" aria-label="Permalink to &quot;引子：一张被遗忘的快照&quot;">​</a></h2><p>1978年冬，北京西单路口。</p><p>一面砖墙上贴满了大字报，围观的人从清晨站到深夜。有人踮脚抄录，有人低声争论，有人从外地坐火车专程赶来看。魏京生的《第五个现代化》贴在墙上最显眼的位置，旁边是王希哲论民主与法制的长文。路过的工人、学生、干部、退休老人，都在读，都在想，都在说。</p><p>那是四十八年前的事了。</p><p>2026年的今天，如果你问一个二十多岁的年轻人&quot;你对公共事务有什么看法&quot;，最常见的回答不是愤怒，不是反对，甚至不是敷衍。是<strong>茫然</strong>。不是&quot;不敢说&quot;，而是&quot;不知道说什么&quot;&quot;不知道为什么要说&quot;&quot;不知道说了有什么用&quot;。</p><p>从&quot;人人都在谈&quot;到&quot;人人都不谈&quot;，中间隔了不到五十年。</p><p>这篇文章要做的，不是控诉，不是怀旧，不是呼吁。它只做一件事：<strong>把这四十年的退潮过程，像解剖一样拆开来看。</strong> 看看每一个阶段发生了什么，什么机制在起作用，什么东西被留下了，什么东西永远消失了。</p><p>因为只有看清了沉默是怎么长出来的，才有可能知道它能不能被拆掉。</p><h2 id="第一章-沸腾-1976-1989" tabindex="-1">第一章：沸腾（1976-1989） <a class="header-anchor" href="#第一章-沸腾-1976-1989" aria-label="Permalink to &quot;第一章：沸腾（1976-1989）&quot;">​</a></h2><h3 id="一、高压解除后的自然释放" tabindex="-1">一、高压解除后的自然释放 <a class="header-anchor" href="#一、高压解除后的自然释放" aria-label="Permalink to &quot;一、高压解除后的自然释放&quot;">​</a></h3><p>1976年&quot;四人帮&quot;倒台之后，中国社会经历了一场近乎本能的公共表达爆发。这不是任何组织动员的结果，也不是知识分子精英设计的结果。它是<strong>一整个民族在长期失语之后的生理性反应</strong>——就像一个人被捂住嘴太久，手一松开，他会不由自主地大口呼吸。</p><p><strong>伤痕文学是第一波浪潮。</strong> 1977年刘心武发表《班主任》，1978年卢新华发表《伤痕》。这些小说在文学史上或许不算杰作，但它们的发行量动辄数百万册，读者来信堆满编辑部。人们读的不是&quot;文学&quot;，他们读的是<strong>自己终于被允许说出口的经历</strong>。&quot;文革&quot;十年的创伤第一次以公开的、合法的、被印刷成铅字的形式进入了公共视野。</p><p><strong>西单民主墙是高潮。</strong> 1978年底到1979年初，北京西单路口的大字报运动持续了数月。参与者不限于知识分子和异见者，大量普通工人、市民、退伍军人也加入了讨论。议题涵盖历史评价、政治体制改革、人权保障、经济改革方向。这不是小圈子的沙龙，这是<strong>真正意义上的街头公共领域</strong>。</p><p><strong>1980年代的&quot;文化热&quot;是持续的制度化表达。</strong> 《读书》杂志成为思想阵地，&quot;走向未来&quot;丛书、&quot;文化：中国与世界&quot;编委会等民间学术团体活跃，大学里的讲座场场爆满，哲学、历史、政治学是最热门的专业。知识分子的公共角色不是自封的，是被社会需要所确认的——人们真的在听，真的在想，真的在追问&quot;中国往何处去&quot;。</p><h3 id="二、为什么那个年代能谈" tabindex="-1">二、为什么那个年代能谈？ <a class="header-anchor" href="#二、为什么那个年代能谈" aria-label="Permalink to &quot;二、为什么那个年代能谈？&quot;">​</a></h3><p>不是因为那个年代的人更勇敢、更有理想主义精神。把原因归结为&quot;人的素质&quot;是一种懒惰的解释。真正的原因是<strong>结构性的</strong>：</p><p><strong>第一，高压刚刚解除，管控机制尚未重建。</strong> &quot;文革&quot;结束后的头几年，旧的意识形态机器处于瘫痪状态，新的管控体系还没有建立起来。这是一个<strong>制度真空期</strong>，公共讨论在这个真空中自然生长。</p><p><strong>第二，执政党内部存在支持公共讨论的力量。</strong> 胡耀邦主导的平反冤假错案、真理标准大讨论、对&quot;两个凡是&quot;的批判——这些自上而下的政治动作，客观上为自下而上的公共表达提供了合法性空间。<strong>当权力内部有人在推动开放时，社会的表达欲望就有了对接点。</strong></p><p><strong>第三，经济利益尚未分化，公共讨论有共同基础。</strong> 1980年代的中国还是一个相对均质的社会。城乡差距、贫富差距、阶层固化都远未达到后来的程度。人们对&quot;改革&quot;有基本共识，分歧主要在&quot;怎么改&quot;而不是&quot;要不要改&quot;。<strong>共同的问题意识让公共讨论成为可能。</strong></p><p><strong>第四，信息渠道单一但未被垄断。</strong> 没有互联网，也没有多元化的媒体市场。但正因如此，《人民日报》《光明日报》《读书》等少数平台承担了公共讨论的功能，且这些平台在当时具有一定的自主性。<strong>信息的集中反而促成了讨论的聚焦。</strong></p><h3 id="三、沸腾的本质" tabindex="-1">三、沸腾的本质 <a class="header-anchor" href="#三、沸腾的本质" aria-label="Permalink to &quot;三、沸腾的本质&quot;">​</a></h3><p>1976-1989年的公共讨论热潮，本质上是一个<strong>后极权社会在转型初期的正常现象</strong>。它不是异常，不是奇迹，不是&quot;黄金时代&quot;的浪漫化想象。它是任何一个经历了长期高压的社会在压力释放时的必然反应。</p><p><strong>它的珍贵之处不在于它有多美好，而在于它证明了中国人并非&quot;天生政治冷漠&quot;。</strong> 当条件允许时，他们会谈论、会思考、会组织、会追问。所谓&quot;国民性&quot;中的冷漠成分，不是文化基因，而是<strong>制度训练的产物</strong>。</p><p>而这个训练，即将开始。</p><h2 id="第二章-断裂-1989-1992" tabindex="-1">第二章：断裂（1989-1992） <a class="header-anchor" href="#第二章-断裂-1989-1992" aria-label="Permalink to &quot;第二章：断裂（1989-1992）&quot;">​</a></h2><h3 id="一、不是一刀切-是一次系统性拆除" tabindex="-1">一、不是一刀切，是一次系统性拆除 <a class="header-anchor" href="#一、不是一刀切-是一次系统性拆除" aria-label="Permalink to &quot;一、不是一刀切，是一次系统性拆除&quot;">​</a></h3><p>1989年之后发生的事情，通常被简化为&quot;镇压&quot;。但&quot;镇压&quot;只是表象。真正具有长期后果的，是一场<strong>针对公共讨论基础设施的系统性拆除</strong>。</p><p><strong>刊物停办。</strong> 《世界经济导报》被查封，《新观察》停刊，大量地方性思想文化类期刊被整顿。公共讨论失去了最重要的载体。</p><p><strong>民间组织解散。</strong> &quot;走向未来&quot;丛书编委会、&quot;文化：中国与世界&quot;编委会、各种民间研究所和沙龙被取缔或被迫停止活动。公共讨论失去了组织网络。</p><p><strong>人员处理。</strong> 活跃的知识分子、记者、编辑、教师、学生被处分、解职、监禁或流亡。不是只处理了&quot;带头人&quot;，而是处理了<strong>整个讨论网络的节点人物</strong>。当一个网络的关键节点被移除后，即使剩余节点还在，网络功能也已瘫痪。</p><p><strong>大学清洗。</strong> 高校思想政治教育全面强化，公共讨论类课程被调整，活跃师生被处理。大学从公共讨论的孵化器变成了<strong>思想管控的第一线</strong>。</p><h3 id="二、心理关联的一次性建立" tabindex="-1">二、心理关联的一次性建立 <a class="header-anchor" href="#二、心理关联的一次性建立" aria-label="Permalink to &quot;二、心理关联的一次性建立&quot;">​</a></h3><p>比物理拆除更重要的，是<strong>心理层面的重新编程</strong>。</p><p>1979年西单民主墙被叫停时，人们学到的是&quot;有些话不能说&quot;——这是一个<strong>边界问题</strong>。你知道红线在哪里，你可以在红线以内继续讨论。</p><p>1989年之后，人们学到的是&quot;谈政治这件事本身是危险的&quot;——这是一个<strong>领域问题</strong>。不再是&quot;哪些话不能说&quot;，而是&quot;这个领域整体上是不可进入的&quot;。</p><p>这种心理关联的建立不需要覆盖每一个人。它只需要<strong>足够多的可见案例</strong>。当你的同事、朋友、老师、邻居中有人因为&quot;谈了&quot;而付出代价时，你不需要亲身经历就会完成自我审查的程序安装。</p><p><strong>恐惧的传播效率远高于勇气的传播效率。</strong> 一百个人勇敢地发言，可能激励一千人；但一个人因为发言而被惩罚，可能吓住一万人。这是不对称的。</p><h3 id="三、断裂的后果-公共讨论参与者的骤然缩减" tabindex="-1">三、断裂的后果：公共讨论参与者的骤然缩减 <a class="header-anchor" href="#三、断裂的后果-公共讨论参与者的骤然缩减" aria-label="Permalink to &quot;三、断裂的后果：公共讨论参与者的骤然缩减&quot;">​</a></h3><p>1989年之前，公共讨论的参与者是一个<strong>光谱</strong>：从激进异见者到温和改革派到普通关心时政的市民到偶尔参与讨论的工人农民。这个光谱的宽度决定了公共讨论的社会基础。</p><p>1989年之后，这个光谱被<strong>压缩成了一个点</strong>。只有极少数愿意承受极高代价的人还在坚持。其余所有人——从温和派到普通市民到工人农民——都被推到了光谱之外。</p><p><strong>这不是&quot;大多数人选择了沉默&quot;。这是&quot;大多数人被剥夺了继续参与的条件&quot;。</strong> 选择意味着你有选项。而当参与的代价高到超出绝大多数人的承受范围时，&quot;不参与&quot;就不是选择，而是<strong>唯一可行的生存策略</strong>。</p><p>这个区别至关重要。如果我们把1989年之后的沉默理解为&quot;人们的选择&quot;，我们就会得出&quot;中国人骨子里就是冷漠的&quot;这种错误结论。但如果我们把它理解为&quot;条件的剥夺&quot;，我们就能看到：<strong>沉默不是原因，是结果。而结果是可逆的，只要条件改变。</strong></p><p>问题是：条件改变了多少？</p><h2 id="第三章-大交易-1992-2003" tabindex="-1">第三章：大交易（1992-2003） <a class="header-anchor" href="#第三章-大交易-1992-2003" aria-label="Permalink to &quot;第三章：大交易（1992-2003）&quot;">​</a></h2><h3 id="一、五个字的契约" tabindex="-1">一、五个字的契约 <a class="header-anchor" href="#一、五个字的契约" aria-label="Permalink to &quot;一、五个字的契约&quot;">​</a></h3><p>1992年，邓小平南巡讲话。&quot;发展是硬道理。&quot;</p><p>这五个字开启了一个隐性的、从未被写入任何法律文件的、但比任何宪法条款都更具约束力的社会契约：</p><blockquote><p><strong>你不谈政治，我让你赚钱。</strong></p></blockquote><p>这不是威胁，这是<strong>交换</strong>。而且是一笔对双方都有利的交换。对于执政者来说，它换取了政治稳定；对于普通人来说，它换取了生活水平的实质性提升。1992年到2003年，中国GDP年均增长超过9%，数亿人脱贫，城市化加速，消费品从短缺变为过剩。</p><p><strong>这笔交易之所以有效，恰恰因为它不是强迫的。它是自愿的。</strong> 没有人拿枪逼你下海经商，没有人禁止你谈政治。只是&quot;谈政治&quot;的收益趋近于零（甚至为负），而&quot;赚钱&quot;的收益清晰可见。在一个理性人模型中，选择是不言自明的。</p><h3 id="二、消费主义作为政治参与的完美替代品" tabindex="-1">二、消费主义作为政治参与的完美替代品 <a class="header-anchor" href="#二、消费主义作为政治参与的完美替代品" aria-label="Permalink to &quot;二、消费主义作为政治参与的完美替代品&quot;">​</a></h3><p>这笔交易的执行机制，不是暴力，而是<strong>消费主义</strong>。</p><p>1990年代的中国，电视上播的是《渴望》《编辑部的故事》《我爱我家》《过把瘾》。全是家长里短、情感纠葛、柴米油盐。没有宏大叙事，没有历史反思，没有公共议题。<strong>私人生活的满足感被建构为人生意义的全部来源。</strong></p><p>&quot;下海&quot;成为时代关键词。知识分子纷纷离开书斋和讲台，投身商海。张维迎、樊纲等经济学家成为明星，不是因为他们的理论多么深刻，而是因为他们的理论<strong>能帮人赚钱</strong>。哲学系招生困难，MBA报名火爆。大学里最热门的讲座不再是萨特和海德格尔，而是股票投资和房地产趋势。</p><p><strong>这不是&quot;人心变了&quot;。这是激励结构变了。</strong> 当整个社会的奖励系统从&quot;公共参与&quot;转向&quot;私人积累&quot;时，人们的行为模式自然会跟着转。指责1990年代的中国人&quot;丧失了理想主义&quot;，就像指责水往低处流一样毫无意义。</p><h3 id="三、-人文精神大讨论-最后的挣扎与象征性的失败" tabindex="-1">三、&quot;人文精神大讨论&quot;：最后的挣扎与象征性的失败 <a class="header-anchor" href="#三、-人文精神大讨论-最后的挣扎与象征性的失败" aria-label="Permalink to &quot;三、&quot;人文精神大讨论&quot;：最后的挣扎与象征性的失败&quot;">​</a></h3><p>1993-1995年，王晓明、张汝伦、陈思和等人发起了&quot;人文精神大讨论&quot;。他们追问：在商业化大潮中，知识分子的精神价值在哪里？市场经济是否正在消解一切超越性的追求？</p><p>这场讨论本身是真诚的、深刻的、有价值的。但它的结局也是象征性的：<strong>它几乎没有激起任何公共回响。</strong></p><p>《读书》杂志发表了相关文章，但读者反馈寥寥。主流媒体不予报道。普通民众完全不关心。甚至连知识界内部，响应者也远少于预期。</p><p><strong>为什么？</strong> 因为这场讨论发生在一个已经完成了激励结构转换的社会中。当&quot;赚钱&quot;已经成为全社会的首要目标时，追问&quot;赚钱之外的意义&quot;就变成了一种<strong>不合时宜的奢侈</strong>。不是人们不同意王晓明们的判断，而是人们<strong>没有动力去认真对待这个判断</strong>。</p><p>&quot;人文精神大讨论&quot;的失败，标志着<strong>1980年代公共讨论传统的正式终结</strong>。此后，知识分子要么进入体制成为技术官僚，要么进入市场成为文化商人，要么退入学院成为专业学者。<strong>&quot;公共知识分子&quot;作为一个社会角色，在中国语境中从此变成了一个贬义词。</strong></p><h3 id="四、大交易的长期后果" tabindex="-1">四、大交易的长期后果 <a class="header-anchor" href="#四、大交易的长期后果" aria-label="Permalink to &quot;四、大交易的长期后果&quot;">​</a></h3><p>这笔交易在短期内是成功的。它实现了经济增长和社会稳定。但它也埋下了长期的隐患：</p><p><strong>第一，公共讨论的能力在一代人之内退化。</strong> 1980年代成长起来的那代人还保留着公共讨论的记忆和技能。但1990年代进入社会的新一代人，从成年起就没有经历过正常的公共讨论环境。他们的社会化过程是在&quot;赚钱+娱乐&quot;的双重框架中完成的。<strong>公共讨论对他们来说不是&quot;被压抑的能力&quot;，而是&quot;从未习得的能力&quot;。</strong></p><p><strong>第二，社会信任的基础从公共规范转向私人关系。</strong> 当公共领域消失后，人们只能依赖私人信任网络来获取信息、解决问题、保障安全。&quot;找关系&quot;&quot;托人情&quot;&quot;圈子文化&quot;不是道德堕落，而是<strong>公共制度缺位时的理性替代方案</strong>。但代价是整个社会的信任半径急剧收缩，制度运行成本飙升。</p><p><strong>第三，执政合法性的基础从意识形态认同转向绩效兑现。</strong> &quot;你不谈政治，我让你赚钱&quot;这个契约的前提是&quot;我能持续让你赚钱&quot;。一旦经济增长放缓、分配不公加剧、社会矛盾累积，这个契约就会面临违约风险。<strong>而当人们已经丧失了用公共讨论来处理矛盾的能力时，矛盾的积累就只能以非理性的方式爆发。</strong></p><p>大交易买来了三十年的稳定。但它透支的是<strong>社会自我修复的能力</strong>。</p><h2 id="第四章-数字幻觉-2003-2015" tabindex="-1">第四章：数字幻觉（2003-2015） <a class="header-anchor" href="#第四章-数字幻觉-2003-2015" aria-label="Permalink to &quot;第四章：数字幻觉（2003-2015）&quot;">​</a></h2><h3 id="一、互联网来了-希望也来了" tabindex="-1">一、互联网来了，希望也来了 <a class="header-anchor" href="#一、互联网来了-希望也来了" aria-label="Permalink to &quot;一、互联网来了，希望也来了&quot;">​</a></h3><p>2003年是一个标志年份。</p><p>孙志刚案——一个大学生因为没有暂住证被收容致死——在传统媒体沉默的情况下，通过网络舆论推动了收容制度的废除。同年，非典期间的信息公开争论也在网络上展开。人们第一次看到：<strong>互联网可以绕过传统媒体的管控，直接形成公共压力，并产生实际政策后果。</strong></p><p>2005-2010年是&quot;网络公共领域&quot;的黄金期。天涯社区、凯迪论坛、新浪博客、各种BBS——人们拥有了前所未有的表达渠道。韩寒的博客点击量过亿，公共知识分子的文章被广泛转载，时事讨论帖动辄数千条回复。</p><p><strong>很多人以为公共讨论回来了。</strong> 他们以为互联网天然地、不可逆转地打开了言论空间。他们以为技术会战胜管控。</p><p>他们错了。</p><h3 id="二、表达-讨论" tabindex="-1">二、表达≠讨论 <a class="header-anchor" href="#二、表达-讨论" aria-label="Permalink to &quot;二、表达≠讨论&quot;">​</a></h3><p>互联网确实带来了表达的爆炸。但它没有带来讨论的复兴。这两者的区别是致命的。</p><p><strong>公共讨论的特征是：</strong></p><ul><li>以理服人而非以势压人；</li><li>倾听对手而非消灭对手；</li><li>追求共识或至少追求相互理解；</li><li>承认自身知识的有限性；</li><li>允许观点被修正。</li></ul><p><strong>网络表达的特征是：</strong></p><ul><li>立场先行，论证后置（甚至没有论证）；</li><li>站队优先，真相次要；</li><li>情绪驱动，逻辑缺席；</li><li>攻击异见者而非回应异见内容；</li><li>140字的篇幅不允许复杂性。</li></ul><p>微博时代的&quot;公共讨论&quot;迅速退化为骂战、站队、人肉搜索、和情绪宣泄。<strong>人们以为自己在&quot;谈国事&quot;，但实际上他们只是在&quot;对国事发泄&quot;。</strong> 发泄完了，什么都没留下。没有共识，没有知识积累，没有可传承的分析框架。每一次热点事件都是一次性的情绪消费，像一根划亮又熄灭的火柴。</p><p><strong>互联网培养了表达的习惯，但没有培养讨论的能力。</strong> 而习惯是可以被管控的，能力才是不可逆的。</p><h3 id="三、管控的进化" tabindex="-1">三、管控的进化 <a class="header-anchor" href="#三、管控的进化" aria-label="Permalink to &quot;三、管控的进化&quot;">​</a></h3><p>与此同时，管控也在进化。</p><p>2003年的删帖是人工的、滞后的、粗糙的。到2010年，关键词过滤、算法审查、账号实名制、平台连带责任已经形成了一套<strong>自动化的、实时的、精细化的管控系统</strong>。</p><p>更重要的是，管控的对象从&quot;内容&quot;扩展到了&quot;平台&quot;。天涯、凯迪等独立平台的衰落，不仅是商业竞争的结果，也是<strong>管控压力下平台自我审查的必然结果</strong>。当平台的生存取决于配合程度时，它会比监管者更积极地审查用户内容。</p><p><strong>互联网没有消灭管控。它只是让管控变得更高效、更低成本、更隐蔽。</strong></p><h3 id="四、幻觉破灭的时刻" tabindex="-1">四、幻觉破灭的时刻 <a class="header-anchor" href="#四、幻觉破灭的时刻" aria-label="Permalink to &quot;四、幻觉破灭的时刻&quot;">​</a></h3><p>2013-2015年间，一系列标志性事件宣告了&quot;网络公共领域&quot;幻象的终结：</p><ul><li>大量公共知识分子账号被封禁或限流；</li><li>独立媒体几乎全部关停或转型；</li><li>网络大V被系统性清理；</li><li>&quot;正能量&quot;成为唯一合法的情绪基调；</li><li>学术研究的选题越来越&quot;安全&quot;，公共讨论类课程被调整。</li></ul><p><strong>人们发现：互联网不是公共讨论的保障，它只是一个暂时的、有条件的、随时可以被收回的窗口。</strong></p><p>而那些在互联网上养成了&quot;表达习惯&quot;但没有培养出&quot;讨论能力&quot;的人，在窗口关闭之后，发现自己既不会讨论了，也不再相信表达有意义了。</p><p><strong>数字幻觉的后果比没有互联网更糟。</strong> 因为没有互联网时，人们至少知道自己缺少什么。而有了互联网又失去它之后，人们体验到的是<strong>希望的给予和撤回</strong>。心理学上，这比从未拥有过希望更能制造绝望。</p><h2 id="第五章-全面冰封-2015-2026" tabindex="-1">第五章：全面冰封（2015-2026） <a class="header-anchor" href="#第五章-全面冰封-2015-2026" aria-label="Permalink to &quot;第五章：全面冰封（2015-2026）&quot;">​</a></h2><h3 id="一、从-删帖-到-预防" tabindex="-1">一、从&quot;删帖&quot;到&quot;预防&quot; <a class="header-anchor" href="#一、从-删帖-到-预防" aria-label="Permalink to &quot;一、从&quot;删帖&quot;到&quot;预防&quot;&quot;">​</a></h3><p>2015年之后，管控发生了质变。</p><p>此前的管控逻辑是<strong>事后反应</strong>：你说了，我删。2015年之后的逻辑是<strong>事前预防</strong>：你在说之前，我就知道你要说什么，并且让你说不出来。</p><p>技术手段包括：</p><ul><li>AI语义分析，识别&quot;擦边球&quot;表达；</li><li>用户画像，预判高风险发言者；</li><li>平台连带责任制，倒逼平台主动加码审查；</li><li>社交关系图谱分析，识别潜在的讨论网络；</li><li>评论区精选、转发限制、搜索屏蔽等精细化管控工具。</li></ul><p><strong>管控的颗粒度从&quot;帖子&quot;细化到了&quot;句子&quot;甚至&quot;词语&quot;。</strong> 你不需要说出完整的批评意见，仅仅使用某些词汇组合就可能触发审查。</p><h3 id="二、空间的消失" tabindex="-1">二、空间的消失 <a class="header-anchor" href="#二、空间的消失" aria-label="Permalink to &quot;二、空间的消失&quot;">​</a></h3><p>如果说2015年之前是&quot;空间收缩&quot;，那么2015年之后是<strong>空间消失</strong>。</p><ul><li>天涯社区关闭；</li><li>凯迪论坛转型为官方宣传平台；</li><li>大量微信公众号被封禁；</li><li>豆瓣小组频繁被清理；</li><li>知乎从公共讨论平台退化为知识付费和种草平台；</li><li>独立媒体几乎归零；</li><li>大学里的公共讨论空间被压缩到极限。</li></ul><p><strong>不是&quot;有些平台还能谈&quot;，而是&quot;没有任何平台还能安全地、持续地、有深度地谈&quot;。</strong> 讨论从公共空间退回到了微信群和私人饭桌——而这些空间本身就是碎片化的、不可积累的、随时可能被渗透的。</p><h3 id="三、语言的污染" tabindex="-1">三、语言的污染 <a class="header-anchor" href="#三、语言的污染" aria-label="Permalink to &quot;三、语言的污染&quot;">​</a></h3><p>这是最隐蔽、也最具长期破坏性的变化。</p><p>2015年之后，一套原本用于分析社会的概念体系被系统性地重新定义：</p><ul><li>&quot;资本&quot;从经济学概念变成了道德指控；</li><li>&quot;阶级&quot;从社会学分析工具变成了敏感词；</li><li>&quot;剥削&quot;从马克思主义核心概念变成了&quot;极左话术&quot;；</li><li>&quot;维权&quot;从法律权利行使变成了&quot;不稳定因素&quot;；</li><li>&quot;公知&quot;从&quot;公共知识分子&quot;的简称变成了侮辱性标签；</li><li>&quot;境外势力&quot;从情报术语变成了万能解释框架；</li><li>&quot;正能量&quot;从心理学概念变成了唯一合法的情绪基调。</li></ul><p><strong>当一套语言被污染之后，人们失去的不是&quot;说话的权利&quot;，而是&quot;说话的工具&quot;。</strong> 你想精确地描述自己的处境，但所有能承载精确含义的词汇都已经被标记、被扭曲、被污名化。你只能用模糊的、安全的、不痛不痒的表达，而那些表达<strong>无法承载真正的分析和追问</strong>。</p><p>这就是为什么今天的公共讨论充斥着情绪而没有分析、充斥着立场而没有论证、充斥着站队而没有对话。<strong>不是人们不想好好说话，是他们已经没有好好说话的词了。</strong></p><h3 id="四、年轻一代的退出" tabindex="-1">四、年轻一代的退出 <a class="header-anchor" href="#四、年轻一代的退出" aria-label="Permalink to &quot;四、年轻一代的退出&quot;">​</a></h3><p>面对这一切，年轻一代的回应不是愤怒，不是反抗，甚至不是犬儒。是<strong>退出</strong>。</p><p>&quot;躺平&quot;：我不参与竞争了。<br> &quot;摆烂&quot;：我不在乎结果了。<br> &quot;润&quot;：我离开这个系统了。<br> &quot;45度人生&quot;：我不卷也不躺，我只是维持最低限度的存在。<br> &quot;电子榨菜&quot;：我用短视频和爽文填充所有空闲时间，不留任何思考的缝隙。</p><p>这些流行语不是政治口号。它们是<strong>政治冷漠的终极形态</strong>。它们的意思是：</p><blockquote><p>我不打算改变这个系统。<br> 我不打算参与这个系统。<br> 我不打算恨这个系统。<br> 我只是<strong>不在这个系统里了</strong>。</p></blockquote><p>这比愤怒更可怕。愤怒至少意味着你还在乎，你还把自己当作这个共同体的一员。躺平和退出意味着<strong>你已经把自己从这个公共体中摘除了</strong>。你不再是&quot;公民&quot;，你只是一个在这个地理空间里谋生的生物体。</p><p><strong>当一个社会的年轻人集体性地从公共生活中退出时，这个社会失去的不是&quot;反对者&quot;，而是&quot;未来的建设者&quot;。</strong> 反对者至少还在场。退出者已经不在了。</p><h2 id="第六章-四十年-一个完整的周期" tabindex="-1">第六章：四十年，一个完整的周期 <a class="header-anchor" href="#第六章-四十年-一个完整的周期" aria-label="Permalink to &quot;第六章：四十年，一个完整的周期&quot;">​</a></h2><h3 id="一、退潮的全景图" tabindex="-1">一、退潮的全景图 <a class="header-anchor" href="#一、退潮的全景图" aria-label="Permalink to &quot;一、退潮的全景图&quot;">​</a></h3><p>时期状态核心机制代际特征1976-1989全民议政高压解除后的自然释放第一代：经历过讨论，保有能力和记忆1989-1992骤然断裂恐惧建立&quot;谈政治=危险&quot;的心理关联第一代被清除，第二代被震慑1992-2003大交易&quot;不谈政治，让你赚钱&quot;——满足替代参与第二代被收买，公共讨论能力开始退化2003-2015数字幻觉互联网制造&quot;回归&quot;错觉，实则培养表达而非讨论第三代在网络环境中成长，习得表达但未习得讨论2015-2026全面冰封技术管控+语言污染+空间消失+代际退出第四代从一开始就不知道&quot;谈&quot;是什么感觉<strong>四十年。四代人。一个完整的从沸腾到冰封的周期。</strong></p><h3 id="二、不可逆吗" tabindex="-1">二、不可逆吗？ <a class="header-anchor" href="#二、不可逆吗" aria-label="Permalink to &quot;二、不可逆吗？&quot;">​</a></h3><p>苏联用了七十年训练沉默。1991年解体时，没有人能为它说一句话。此后花了将近二十年，俄罗斯社会才慢慢恢复了一些公共讨论的能力——而且至今仍未恢复到健康水平。</p><p>中国的四十年沉默训练，速度更快，因为工具更先进。不需要古拉格，不需要秘密警察，不需要大规模逮捕。只需要&quot;发展是硬道理&quot;加一个算法审查系统，再加上一套被污染的语言。</p><p><strong>那么，这个过程是不可逆的吗？</strong></p><p>没有人知道。但有三件事是确定的：</p><p><strong>第一，它不会自动逆转。</strong> 沉默是一种均衡态。在没有外部冲击或内部觉醒的情况下，它会自我维持。每一代新人都在沉默的环境中完成社会化，然后成为下一代沉默环境的维护者。这是一个<strong>自增强循环</strong>。</p><p><strong>第二，逆转的条件不是&quot;放开管控&quot;那么简单。</strong> 即使明天所有审查都取消了，人们也不会自动恢复公共讨论的能力。因为能力已经退化了，语言已经被污染了，信任已经被摧毁了，空间已经被切割了。<strong>解除禁令容易，重建能力难。</strong></p><p><strong>第三，逆转只能从最小的单位开始。</strong> 不是等待顶层设计，不是期待英雄人物，不是指望技术突破。而是从每一个还能说话的地方开始：饭桌上、教室里、文章中、朋友间的对话中。<strong>用精确的语言，把看到的事情说清楚。</strong> 不是为了改变什么，而是为了<strong>保持&quot;说清楚&quot;这个能力本身不死</strong>。</p><h3 id="三、这篇文章本身就是一种练习" tabindex="-1">三、这篇文章本身就是一种练习 <a class="header-anchor" href="#三、这篇文章本身就是一种练习" aria-label="Permalink to &quot;三、这篇文章本身就是一种练习&quot;">​</a></h3><p>你现在读到的这篇文字，就是这种练习的一部分。</p><p>它没有用&quot;境外势力&quot;&quot;觉醒&quot;&quot;反抗&quot;这些已经被污染或空心化的词。它用的是：具体的历史事实、可验证的制度分析、跨时空的比较框架、以及对概念精确性的坚持。</p><p>它不煽动、不对抗、不站队。它只是<strong>把过程说清楚</strong>。</p><p>在一个&quot;莫谈国事&quot;已经成为条件反射的环境里，&quot;把过程说清楚&quot;本身就是一种稀缺的公共行动。不是因为它能改变什么，而是因为它<strong>证明了&quot;说清楚&quot;这个能力还存在</strong>。</p><p>只要这个能力还在，冰封就不是终点。</p><hr><blockquote><p>本文同步自知乎，<a href="https://zhuanlan.zhihu.com/p/2076628512786617334" target="_blank" rel="noreferrer">查看原文</a></p></blockquote>',137)])])}const d=t(n,[["render",q]]);export{h as __pageData,d as default};
